"""Customer endpoints."""

from __future__ import annotations

from typing import Any

from orders.application.customer_service import CustomerService
from orders.application.errors import Conflict, CustomerNotFound
from orders.controllers.http import (InvalidRequest, Response, bad_request, conflict, not_found,
                                     require_str)
from orders.domain.customers import TIERS, Customer


def customer_body(customer: Customer) -> dict[str, Any]:
    return {"customer_id": customer.customer_id, "name": customer.name, "email": customer.email,
            "tier": customer.tier}


class CustomerController:
    def __init__(self, service: CustomerService) -> None:
        self._service = service

    def handle_register(self, request: dict[str, Any]) -> Response:
        try:
            customer_id = require_str(request, "customer_id")
            name = require_str(request, "name")
            email = require_str(request, "email")
            tier = request.get("tier", "standard")
            if tier not in TIERS:
                raise InvalidRequest(f"tier must be one of {', '.join(TIERS)}")
        except InvalidRequest as exc:
            return bad_request(exc)
        try:
            customer = self._service.register(customer_id, name, email, tier)
        except Conflict as exc:
            return conflict(exc)
        return Response(201, customer_body(customer))

    def handle_get(self, customer_id: str) -> Response:
        try:
            return Response(200, customer_body(self._service.get(customer_id)))
        except CustomerNotFound:
            return not_found("customer")

"""Customer insights endpoints."""

from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found


class CustomerInsightsController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_order_history(self, customer_id: str) -> Response:
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")

        order_entries = []
        for order in reversed(orders):
            summary = self._service.summarize(order)
            order_entries.append({
                "order_id": order.order_id,
                "status": order.status,
                "total_cents": summary.total_cents,
            })

        return Response(200, {
            "customer_id": customer_id,
            "orders": order_entries,
        })

    def handle_lifetime_value(self, customer_id: str) -> Response:
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")

        order_count = 0
        lifetime_value_cents = 0
        for order in orders:
            if order.status != "cancelled":
                order_count += 1
                summary = self._service.summarize(order)
                lifetime_value_cents += summary.total_cents

        return Response(200, {
            "customer_id": customer_id,
            "order_count": order_count,
            "lifetime_value_cents": lifetime_value_cents,
        })

    def handle_top_customers(self, limit: Any) -> Response:
        if type(limit) is not int or isinstance(limit, bool) or limit < 1:
            return bad_request(InvalidRequest("limit must be a positive integer"))

        top_customers = self._service.get_top_customers_by_lifetime_value(limit)
        return Response(200, {
            "customers": [
                {
                    "customer_id": customer_id,
                    "name": name,
                    "lifetime_value_cents": lifetime_value_cents,
                }
                for customer_id, name, lifetime_value_cents in top_customers
            ]
        })

    return self._orders.set_status(order_id, "cancelled")

def get_top_customers_by_lifetime_value(self, limit: int) -> list[tuple[str, str, int]]:
    """Return (customer_id, name, lifetime_value_cents) for top customers by lifetime value.

    Sorted by lifetime value descending, then customer_id ascending. Only includes customers
    with non-zero lifetime value. Returns at most `limit` entries.
    """
    customers = self._customers.list_all()
    customer_values = []
    for customer in customers:
        lifetime_value = 0
        for order in self._orders.list_for_customer(customer.customer_id):
            if order.status != "cancelled":
                lifetime_value += self.summarize(order).total_cents
        if lifetime_value > 0:
            customer_values.append((customer.customer_id, customer.name, lifetime_value))

    customer_values.sort(key=lambda x: (-x[2], x[0]))
    return customer_values[:limit]

