    for customer in customers:
        has_non_cancelled = any(
            order.status != "cancelled"
            for order in self._orders.list_for_customer(customer.customer_id)
        )
        if not has_non_cancelled:
            result.append((customer.customer_id, customer.name, customer.email))
    return result
